const fs = require('node:fs');
const path = require('node:path');
const { withDangerousMod, withXcodeProject } = require('expo/config-plugins');

/**
 * Compile the Live Activity's main-app sources into the app target.
 *
 * The Live Activity spans two targets:
 *
 * - The WidgetKit extension renders it. That target is declared in
 *   `targets/live-activity/` and generated by `@bacons/apple-targets`.
 * - The **app** starts, updates and ends activities through a React Native
 *   bridge module. Those sources belong to the main app target, which
 *   apple-targets does not manage.
 *
 * This plugin owns that second half. It copies:
 *
 * - `native/ios/LiveActivityModule.swift` — the ActivityKit calls.
 * - `native/ios/LiveActivityModule.m`     — the `RCT_EXTERN_MODULE` bridge.
 * - `targets/live-activity/EventLiveActivityAttributes.swift` — the shared
 *   `ActivityAttributes`. Copied from the widget target rather than duplicated,
 *   so the app and the extension can never disagree about the model. Both
 *   targets must compile it: the app constructs it, the extension renders it.
 *
 * All three previously lived only inside the gitignored `ios/` directory, so
 * every `expo prebuild` — including EAS's, on every cloud build — deleted them.
 */

/** Sources copied into the main app target, as [source, destination filename]. */
const SOURCES = [
  ['native/ios/LiveActivityModule.swift', 'LiveActivityModule.swift'],
  ['native/ios/LiveActivityModule.m', 'LiveActivityModule.m'],
  [
    'targets/live-activity/EventLiveActivityAttributes.swift',
    'EventLiveActivityAttributes.swift',
  ],
];

function withCopiedSources(config) {
  return withDangerousMod(config, [
    'ios',
    (cfg) => {
      const { projectRoot, platformProjectRoot, projectName } = cfg.modRequest;
      const destDir = path.join(platformProjectRoot, projectName);
      fs.mkdirSync(destDir, { recursive: true });

      for (const [from, filename] of SOURCES) {
        const src = path.join(projectRoot, from);
        if (!fs.existsSync(src)) {
          throw new Error(
            `[with-live-activity-module] Missing source: ${from}. ` +
              'Live Activities will silently stop working if this is skipped.'
          );
        }
        fs.copyFileSync(src, path.join(destDir, filename));
      }

      return cfg;
    },
  ]);
}

function withRegisteredSources(config) {
  return withXcodeProject(config, (cfg) => {
    const project = cfg.modResults;
    const { projectName } = cfg.modRequest;

    const target = project.getFirstTarget();
    if (!target) {
      throw new Error('[with-live-activity-module] Could not find the main app target.');
    }

    const group = project.findPBXGroupKey({ name: projectName });
    if (!group) {
      throw new Error(
        `[with-live-activity-module] Could not find the "${projectName}" group in the Xcode project.`
      );
    }

    for (const [, filename] of SOURCES) {
      // `.m` and `.swift` are both compiled sources. Skip if a previous run of
      // this plugin already added it, so prebuild stays idempotent.
      if (project.hasFile(`${projectName}/${filename}`)) continue;

      project.addSourceFile(
        `${projectName}/${filename}`,
        { target: target.uuid },
        group
      );
    }

    return cfg;
  });
}

module.exports = function withLiveActivityModule(config) {
  return withRegisteredSources(withCopiedSources(config));
};
